import json
import datetime
from zoneinfo import ZoneInfo

SOURCE = "automation:Apply Practice Manager message decision"


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def delete_file(path):
    try:
        api.files.delete(file=path)
    except Exception:
        pass


def audit(slug, tz, action, target, summary, workq_item_id=""):
    # SK-13 format (healthcare-practice-management-foundation): one JSON line per action, practice-local ts.
    now_local = datetime.datetime.now(tz)
    path = "PracticeManager/AuditLog/" + slug + "-" + now_local.strftime("%Y-%m-%d") + ".jsonl"
    line = {
        "ts": now_local.isoformat(timespec="seconds"), "practice_slug": slug, "actor": "agent",
        "source": SOURCE, "action": action, "target": target, "summary": summary,
    }
    if workq_item_id:
        line["workq_item_id"] = workq_item_id
    try:
        try:
            existing = api.files.read(file=path) or ""
        except Exception:
            existing = ""
        if existing and not existing.endswith("\n"):
            existing += "\n"
        api.files.put(file=path, content=existing + json.dumps(line, sort_keys=True) + "\n")
    except Exception:
        pass


responses = params.get("responses") or {}
todo_id = params.get("todo_id") or ""
outcome = "ignored"

if responses and todo_id:
    draft_path = "PracticeManager/Drafts/" + todo_id + ".json"
    draft = read_json(draft_path, None)
    if not draft:
        api.workq.comment(todo_id=todo_id, body="Couldn't find the drafted message for this item - nothing was sent.")
        outcome = "draft_missing"
    else:
        kind = draft.get("kind") or "message"
        slug = draft.get("slug") or ""
        practice = read_json("PracticeManager/Practices/" + slug + ".json", {}) or {}
        try:
            tz = ZoneInfo(practice.get("timezone") or "Australia/Sydney")
        except Exception:
            tz = datetime.timezone.utc
        decision = str(responses.get("q_decision") or "")
        edited = str(responses.get("q_edited_message") or "").strip()
        patient_name = draft.get("patient_name") or "the patient"
        target = {"kind": "email", "id": todo_id}

        if decision == "Don't send":
            api.workq.comment(todo_id=todo_id, body="Marked as don't send. No message was sent to " + patient_name + ".")
            api.workq.complete(todo_id=todo_id)
            audit(slug, tz, "rejected", target, "Reviewer chose not to send the drafted message to " + patient_name, todo_id)
            delete_file(draft_path)
            outcome = "not_sent"
        else:
            use_edit = decision == "Edit and send" and bool(edited)
            body = edited if use_edit else (draft.get("body") or "")
            subject = draft.get("subject") or "A message from the practice"
            email = draft.get("email") or ""
            provider = str(practice.get("email_provider") or "outlook")

            if not email:
                api.workq.comment(todo_id=todo_id, body="No email on file for " + patient_name + " - nothing was sent. Send it another way if needed.")
                outcome = "no_email"
            elif provider != "outlook":
                # Gmail has no send tool in this workspace - never claim it was sent.
                note = (
                    "This practice's email provider is Gmail, which can't send from automations yet. "
                    "Please send this yourself:\n\n**To:** " + email + "\n**Subject:** " + subject + "\n\n" + body
                )
                if kind == "reschedule_offer":
                    note += "\n\n_Their reply won't be read automatically for a Gmail practice - book the time they pick by hand in Cliniko._"
                api.workq.comment(todo_id=todo_id, body=note)
                outcome = "needs_manual_send"
            else:
                sent_at = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=5)).strftime("%Y-%m-%dT%H:%M:%SZ")
                try:
                    api.connectors.invoke(
                        server="m365-mail-send", tool="send_email",
                        args={"to": [email], "subject": subject, "body": body, "contentType": "Text"},
                    )
                    send_error = ""
                except Exception as exc:
                    send_error = str(exc)

                if send_error:
                    api.workq.comment(todo_id=todo_id, body="Sending to " + email + " failed, so nothing was sent: " + send_error + "\n\nResubmit the form to try again, or send it yourself.")
                    outcome = "send_failed"
                else:
                    if use_edit:
                        audit(slug, tz, "edited", target, "Reviewer edited the drafted message to " + patient_name + " before sending", todo_id)
                    audit(slug, tz, "sent", target, "Sent the approved message to " + patient_name, todo_id)
                    delete_file(draft_path)

                    if kind == "reschedule_offer":
                        # send_email returns no message id - find the sent copy to learn its conversationId, so
                        # the reply reader can match the patient's answer to this offer. Falls back to matching
                        # by sender address when the sent copy can't be found.
                        conversation_id = ""
                        try:
                            sent = api.connectors.invoke(
                                server="m365-mail-read", tool="list_emails",
                                args={"folder": "sentitems", "limit": 10, "receivedAfter": sent_at},
                            )
                            sent = sent if isinstance(sent, list) else ((sent or {}).get("value") or [])
                            for m in sent:
                                to = [((r or {}).get("emailAddress") or {}).get("address", "").lower() for r in (m.get("toRecipients") or [])]
                                if email.lower() in to and (m.get("subject") or "") == subject:
                                    conversation_id = m.get("conversationId") or ""
                                    break
                        except Exception:
                            conversation_id = ""
                        state = dict(draft)
                        state.update({"todo_id": todo_id, "body": body, "sent_at": sent_at, "conversation_id": conversation_id})
                        write_json("PracticeManager/AwaitingReply/" + todo_id + ".json", state)
                        api.workq.comment(
                            todo_id=todo_id,
                            body=(
                                "Sent to " + email + ". Waiting for their reply - the time they pick will be booked "
                                "automatically (after re-checking it is still free) and this item closed. Unclear "
                                "replies, or no reply within 7 days, come back here for you to handle."
                            ),
                        )
                        outcome = "sent_awaiting_reply"
                    else:
                        api.workq.comment(todo_id=todo_id, body="Sent to " + email + ".")
                        api.workq.complete(todo_id=todo_id)
                        outcome = "sent"
